+func TestLookup(t *testing.T) {
+	a := &Archive{
+		Comment: []byte("comment\n"),
+		Files: []File{
+			{"foo", []byte("data1")},
+			{"bar", []byte("data2")},
+		},
+	}
+	// Found
+	f, ok := a.Lookup("foo")
+	if !ok || f.Name != "foo" || string(f.Data) != "data1" {
+		t.Fatalf("Lookup(\"foo\") = (%q, %v), want (%q, true)", f.Name, ok, "foo")
+	}
+	// Not found
+	f, ok = a.Lookup("baz")
+	if ok || f != nil {
+		t.Fatalf("Lookup(\"baz\") = (%q, %v), want (nil, false)", f, ok)
+	}
+}
